using Agro360.Application.Contracts;
using Agro360.Infrastructure.Persistence;
using Agro360.Multitenancy;
using Agro360.SharedKernel;
using Dapper;
using Npgsql;

namespace Agro360.Infrastructure.Services;

public sealed class Livestock360Service(DatabaseExecutor db, ITenantContext tenant) : ILivestock360Service
{
    public Task<dynamic?> GetAnimalAsync(Guid id,CancellationToken ct)=>Tx(async(c,t)=>await c.QuerySingleOrDefaultAsync(new CommandDefinition("select * from livestock.animals where tenant_id=@TenantId and id=@Id and deleted_at is null",new{tenant.TenantId,Id=id},t,cancellationToken:ct)));
    public Task<dynamic> UpdateAnimalAsync(Guid id,RegisterAnimalCommand x,CancellationToken ct)=>Tx<dynamic>(async(c,t)=>{ ValidateWeight(null); var n=await c.ExecuteAsync(new CommandDefinition("update livestock.animals set farm_id=@FarmId,herd_id=@HerdId,tag=@Tag,rfid=@Rfid,species=@Species,breed=@Breed,sex=@Sex,birth_date=@BirthDate,mother_id=@MotherId,father_id=@FatherId,updated_at=now(),updated_by=@UserId,version=version+1 where tenant_id=@TenantId and id=@Id",new{x.FarmId,x.HerdId,Tag=Guard.Required(x.Tag,nameof(x.Tag),80),x.Rfid,x.Species,x.Breed,x.Sex,x.BirthDate,x.MotherId,x.FatherId,tenant.TenantId,tenant.UserId,Id=id},t,cancellationToken:ct));if(n==0)throw new NotFoundException("Animal",id);await Audit(c,t,"update","Animal",id,x,ct);return await c.QuerySingleAsync(new CommandDefinition("select * from livestock.animals where tenant_id=@TenantId and id=@Id",new{tenant.TenantId,Id=id},t,cancellationToken:ct));});
    public Task ChangeAnimalStatusAsync(Guid id,string status,AnimalStatusCommand x,CancellationToken ct)=>Tx(async(c,t)=>{var code=status switch{"DEAD"=>4,"SOLD"=>3,"DISCARDED"=>5,_=>throw new DomainException("Status inválido.","livestock.status_invalid")};var n=await c.ExecuteAsync(new CommandDefinition("update livestock.animals set status=@Code,updated_at=now(),updated_by=@UserId,version=version+1 where tenant_id=@TenantId and id=@Id and status in (1,2,6); insert into livestock.animal_events(id,tenant_id,animal_id,event_type,occurred_on,data,created_at,created_by) select @EventId,@TenantId,@Id,@Status,@On,jsonb_build_object('reason',@Reason),now(),@UserId where exists(select 1 from livestock.animals where tenant_id=@TenantId and id=@Id and status=@Code)",new{Code=code,tenant.TenantId,tenant.UserId,Id=id,EventId=Guid.CreateVersion7(),Status=status,On=x.OccurredOn,x.Reason},t,cancellationToken:ct));if(n<2)throw new ConflictException("Animal inexistente ou inativo.","livestock.animal_not_active");await Audit(c,t,status.ToLowerInvariant(),"Animal",id,x,ct);});
    public Task TransferAnimalAsync(Guid id,AnimalTransferCommand x,CancellationToken ct)=>Tx(async(c,t)=>{var old=await c.QuerySingleOrDefaultAsync<dynamic>(new CommandDefinition("select farm_id,paddock_id,status from livestock.animals where tenant_id=@TenantId and id=@Id for update",new{tenant.TenantId,Id=id},t,cancellationToken:ct))??throw new NotFoundException("Animal",id);await c.ExecuteAsync(new CommandDefinition("update livestock.animals set farm_id=@FarmId,paddock_id=@PaddockId,updated_at=now(),updated_by=@UserId,version=version+1 where tenant_id=@TenantId and id=@Id; insert into livestock.animal_movements(id,tenant_id,animal_id,from_farm_id,to_farm_id,from_paddock_id,to_paddock_id,moved_on,notes,created_at,created_by) values(@Movement,@TenantId,@Id,@OldFarm,@FarmId,@OldPaddock,@PaddockId,@On,@Notes,now(),@UserId)",new{x.FarmId,x.PaddockId,tenant.TenantId,tenant.UserId,Id=id,Movement=Guid.CreateVersion7(),OldFarm=(Guid)old.farm_id,OldPaddock=(Guid?)old.paddock_id,On=x.OccurredOn,x.Notes},t,cancellationToken:ct));await Audit(c,t,"transfer","Animal",id,x,ct);});
    public Task<IReadOnlyList<dynamic>> ListHerdsAsync(CancellationToken ct)=>List("select * from livestock.herds where tenant_id=@TenantId and active order by name",ct);
    public Task<Guid> SaveHerdAsync(Guid? id,HerdCommand x,CancellationToken ct)=>Upsert("livestock.herds",id,"farm_id,name,species,category,head_count,active","@FarmId,@Name,@Species,@Category,@HeadCount,true","farm_id=@FarmId,name=@Name,species=@Species,category=@Category,head_count=@HeadCount",x,ct);
    public Task<IReadOnlyList<dynamic>> ListPasturesAsync(CancellationToken ct)=>List("select p.*,count(k.id) paddocks from livestock.pastures p left join livestock.paddocks k on k.pasture_id=p.id where p.tenant_id=@TenantId group by p.id order by p.name",ct);
    public Task<Guid> SavePastureAsync(Guid? id,PastureCommand x,CancellationToken ct){if(x.AreaHectares<=0)throw new DomainException("Área deve ser positiva.","pasture.area_invalid");return Upsert("livestock.pastures",id,"farm_id,name,area_hectares,forage_type,status","@FarmId,@Name,@AreaHectares,@ForageType,@Status","farm_id=@FarmId,name=@Name,area_hectares=@AreaHectares,forage_type=@ForageType,status=@Status",x,ct);}
    public Task<IReadOnlyList<dynamic>> ListPaddocksAsync(CancellationToken ct)=>List("select p.*,coalesce(o.occupancy,0) occupancy,(coalesce(o.occupancy,0)>p.capacity_au) overcapacity from livestock.paddocks p left join lateral(select count(*) occupancy from livestock.animals a where a.tenant_id=p.tenant_id and a.paddock_id=p.id and a.status in(1,2,6))o on true where p.tenant_id=@TenantId order by p.name",ct);
    public Task<Guid> SavePaddockAsync(Guid? id,PaddockCommand x,CancellationToken ct){if(x.AreaHectares<=0||x.CapacityAu<0||x.RestDays<0||x.OccupationDays<0)throw new DomainException("Valores de piquete inválidos.","pasture.values_invalid");return Upsert("livestock.paddocks",id,"pasture_id,name,area_hectares,capacity_au,status,rest_days,occupation_days,entry_height_cm,exit_height_cm,forage_mass_kg_ha","@PastureId,@Name,@AreaHectares,@CapacityAu,@Status,@RestDays,@OccupationDays,@EntryHeightCm,@ExitHeightCm,@ForageMassKgHa","pasture_id=@PastureId,name=@Name,area_hectares=@AreaHectares,capacity_au=@CapacityAu,status=@Status,rest_days=@RestDays,occupation_days=@OccupationDays,entry_height_cm=@EntryHeightCm,exit_height_cm=@ExitHeightCm,forage_mass_kg_ha=@ForageMassKgHa",x,ct);}
    public Task MovePaddockAsync(Guid id,bool occupy,PaddockMovementCommand x,CancellationToken ct)=>Tx(async(c,t)=>{var p=await c.QuerySingleOrDefaultAsync<dynamic>(new CommandDefinition("select status,last_released_at,rest_days from livestock.paddocks where tenant_id=@TenantId and id=@Id for update",new{tenant.TenantId,Id=id},t,cancellationToken:ct))??throw new NotFoundException("Piquete",id);if(occupy&&((string)p.status=="INACTIVE"||(string)p.status=="INATIVA"))throw new ConflictException("Piquete inativo não pode ser ocupado.","pasture.inactive");if(x.AnimalId is null&&x.HerdId is null)throw new DomainException("Informe animal ou lote.","livestock.subject_required");var eventId=Guid.CreateVersion7();await c.ExecuteAsync(new CommandDefinition("insert into livestock.paddock_movements(id,tenant_id,paddock_id,origin_paddock_id,animal_id,herd_id,movement_type,occurred_at,notes,created_by) values(@EventId,@TenantId,@Id,@Origin,@Animal,@Herd,@Type,@At,@Notes,@UserId); update livestock.paddocks set status=@Status,last_occupied_at=case when @Occupy then @At else last_occupied_at end,last_released_at=case when @Occupy then last_released_at else @At end,updated_at=now() where tenant_id=@TenantId and id=@Id; update livestock.animals set paddock_id=case when @Occupy then @Id else null end,updated_at=now(),version=version+1 where tenant_id=@TenantId and ((@Animal is not null and id=@Animal) or (@Herd is not null and herd_id=@Herd))",new{EventId=eventId,tenant.TenantId,Id=id,Origin=x.OriginPaddockId,Animal=x.AnimalId,Herd=x.HerdId,Type=occupy?"ENTRY":"EXIT",At=x.OccurredAt,x.Notes,tenant.UserId,Status=occupy?"IN_USE":"RESTING",Occupy=occupy},t,cancellationToken:ct));await Audit(c,t,occupy?"occupy":"release","Paddock",id,x,ct);});
    public Task<IReadOnlyList<dynamic>> ListEventsAsync(string kind,CancellationToken ct){var table=kind switch{"handling"=>"handling_events","health"=>"health_events","reproduction"=>"reproduction_events",_=>throw new DomainException("Tipo inválido.","livestock.event_type_invalid")};return List($"select * from livestock.{table} where tenant_id=@TenantId order by occurred_on desc limit 500",ct);}
    public Task<Guid> AddHandlingAsync(HandlingEventCommand x,CancellationToken ct)=>Tx(async(c,t)=>{if(x.AnimalId is null&&x.HerdId is null)throw new DomainException("Informe animal ou lote.","livestock.subject_required");if(x.WeightKg<0||x.EstimatedCost<0)throw new DomainException("Peso e custo não podem ser negativos.","livestock.handling_values_invalid");var id=Guid.CreateVersion7();await c.ExecuteAsync(new CommandDefinition("insert into livestock.handling_events(id,tenant_id,animal_id,herd_id,event_type,occurred_on,responsible,notes,weight_kg,body_score,paddock_id,estimated_cost,created_by) values(@Id,@TenantId,@AnimalId,@HerdId,@Type,@OccurredOn,@Responsible,@Notes,@WeightKg,@BodyScore,@PaddockId,@EstimatedCost,@UserId); update livestock.animals set current_weight_kg=coalesce(@WeightKg,current_weight_kg),last_weight_date=case when @WeightKg is null then last_weight_date else @OccurredOn end,status=case when upper(@Type)='MORTALITY' then 4 when upper(@Type)='SALE' then 3 when upper(@Type)='DISCARD' then 5 else status end,version=version+1,updated_at=now() where tenant_id=@TenantId and id=@AnimalId and status in(1,2,6)",new{Id=id,tenant.TenantId,x.AnimalId,x.HerdId,x.Type,x.OccurredOn,x.Responsible,x.Notes,x.WeightKg,x.BodyScore,x.PaddockId,x.EstimatedCost,tenant.UserId},t,cancellationToken:ct));await Audit(c,t,"create","HandlingEvent",id,x,ct);return id;});
    public Task<Guid> AddHealthAsync(HealthEventCommand x,CancellationToken ct)=>Tx(async(c,t)=>{if(x.Dose<=0)throw new DomainException("Dose deve ser positiva.","livestock.dose_invalid");if(x.WithdrawalDays<0)throw new DomainException("Carência inválida.","livestock.withdrawal_invalid");var id=Guid.CreateVersion7();await Consume(c,t,x.WarehouseId,x.ProductId,x.Dose,x.Unit,id,"HEALTH_EVENT",ct);await c.ExecuteAsync(new CommandDefinition("insert into livestock.health_events(id,tenant_id,animal_id,herd_id,event_type,occurred_on,dose,unit,product_id,withdrawal_until,next_application,technician,diagnosis,notes,cost_amount,created_by) values(@Id,@TenantId,@AnimalId,@HerdId,@Type,@AppliedOn,@Dose,@Unit,@ProductId,@Withdrawal,@NextApplication,@Technician,@Diagnosis,@Notes,0,@UserId); update livestock.animals set withdrawal_until=greatest(coalesce(withdrawal_until,@Withdrawal),@Withdrawal),version=version+1,updated_at=now() where tenant_id=@TenantId and id=@AnimalId",new{Id=id,tenant.TenantId,x.AnimalId,x.HerdId,x.Type,x.AppliedOn,x.Dose,x.Unit,x.ProductId,Withdrawal=x.AppliedOn.AddDays(x.WithdrawalDays),x.NextApplication,x.Technician,x.Diagnosis,x.Notes,tenant.UserId},t,cancellationToken:ct));await Audit(c,t,"create","HealthEvent",id,x,ct);return id;});
    public Task<Guid> AddReproductionAsync(ReproductionEventCommand x,CancellationToken ct)=>Tx(async(c,t)=>{var female=await c.QuerySingleOrDefaultAsync<dynamic>(new CommandDefinition("select sex,status,species,farm_id from livestock.animals where tenant_id=@TenantId and id=@Id for update",new{tenant.TenantId,Id=x.FemaleId},t,cancellationToken:ct))??throw new NotFoundException("Matriz",x.FemaleId);if(!new[]{"F","FEMALE","FEMEA","FÊMEA"}.Contains(((string)female.sex).ToUpperInvariant()))throw new DomainException("Somente fêmeas podem receber evento reprodutivo.","livestock.female_required");if((short)female.status is not (1 or 2 or 6))throw new ConflictException("Matriz não está ativa.");var type=x.Type.ToUpperInvariant();if(type is "INSEMINATION" or "NATURAL_SERVICE"){var active=await c.ExecuteScalarAsync<bool>(new CommandDefinition("select exists(select 1 from livestock.reproduction_cycles where tenant_id=@TenantId and female_id=@FemaleId and status='ACTIVE')",new{tenant.TenantId,x.FemaleId},t,cancellationToken:ct));if(active)throw new ConflictException("Já existe ciclo reprodutivo ativo.","livestock.reproduction_conflict");}var id=Guid.CreateVersion7();DateOnly? due=type=="PREGNANCY_DIAGNOSIS"&&x.Positive==true?x.OccurredOn.AddDays(GestationDays((string)female.species)):null;await c.ExecuteAsync(new CommandDefinition("insert into livestock.reproduction_events(id,tenant_id,female_id,sire_id,event_type,occurred_on,genetic_lot,positive,expected_birth_on,notes,created_by) values(@Id,@TenantId,@FemaleId,@SireId,@Type,@OccurredOn,@GeneticLot,@Positive,@Due,@Notes,@UserId); insert into livestock.reproduction_cycles(id,tenant_id,female_id,started_on,status,expected_birth_on,created_by) select @Cycle,@TenantId,@FemaleId,@OccurredOn,'ACTIVE',@Due,@UserId where @Type in('INSEMINATION','NATURAL_SERVICE'); update livestock.reproduction_cycles set expected_birth_on=@Due,status=case when @Positive=false then 'CLOSED' else status end,updated_at=now() where tenant_id=@TenantId and female_id=@FemaleId and status='ACTIVE' and @Type='PREGNANCY_DIAGNOSIS'; update livestock.reproduction_cycles set status='CLOSED',ended_on=@OccurredOn,updated_at=now() where tenant_id=@TenantId and female_id=@FemaleId and status='ACTIVE' and @Type in('BIRTH','ABORTION')",new{Id=id,tenant.TenantId,x.FemaleId,x.SireId,Type=type,x.OccurredOn,x.GeneticLot,x.Positive,Due=due,x.Notes,tenant.UserId,Cycle=Guid.CreateVersion7()},t,cancellationToken:ct));if(type=="BIRTH"&&x.CreateCalf){if(string.IsNullOrWhiteSpace(x.CalfTag))throw new DomainException("Identificação da cria é obrigatória.","livestock.calf_tag_required");await c.ExecuteAsync(new CommandDefinition("insert into livestock.animals(id,tenant_id,farm_id,tag,species,breed,sex,birth_date,mother_id,status,created_at,created_by,version) values(@Calf,@TenantId,@Farm,@Tag,@Species,'NÃO INFORMADA','U',@Born,@Mother,1,now(),@UserId,1)",new{Calf=Guid.CreateVersion7(),tenant.TenantId,Farm=(Guid)female.farm_id,Tag=x.CalfTag,Species=(string)female.species,Born=x.OccurredOn,Mother=x.FemaleId,tenant.UserId},t,cancellationToken:ct));}await Audit(c,t,"create","ReproductionEvent",id,x,ct);return id;});
    public Task<IReadOnlyList<dynamic>> ListNutritionPlansAsync(CancellationToken ct)=>List("select p.*,coalesce(sum(i.quantity_per_day*i.unit_cost),0) daily_cost from livestock.nutrition_plans p left join livestock.nutrition_plan_items i on i.plan_id=p.id where p.tenant_id=@TenantId group by p.id order by p.starts_on desc",ct);
    public Task<Guid> AddNutritionPlanAsync(NutritionPlanCommand x,CancellationToken ct)=>Tx(async(c,t)=>{if(x.Items.Count==0||x.Items.Any(i=>i.QuantityPerDay<=0||i.UnitCost<0))throw new DomainException("Dieta deve possuir itens válidos.","livestock.diet_invalid");var id=Guid.CreateVersion7();await c.ExecuteAsync(new CommandDefinition("insert into livestock.nutrition_plans(id,tenant_id,farm_id,herd_id,name,starts_on,ends_on,status,created_by) values(@Id,@TenantId,@FarmId,@HerdId,@Name,@StartsOn,@EndsOn,'ACTIVE',@UserId)",new{Id=id,tenant.TenantId,x.FarmId,x.HerdId,x.Name,x.StartsOn,x.EndsOn,tenant.UserId},t,cancellationToken:ct));foreach(var i in x.Items)await c.ExecuteAsync(new CommandDefinition("insert into livestock.nutrition_plan_items(id,tenant_id,plan_id,product_id,quantity_per_day,unit,unit_cost) values(@Id,@TenantId,@Plan,@ProductId,@QuantityPerDay,@Unit,@UnitCost)",new{Id=Guid.CreateVersion7(),tenant.TenantId,Plan=id,i.ProductId,i.QuantityPerDay,i.Unit,i.UnitCost},t,cancellationToken:ct));await Audit(c,t,"create","NutritionPlan",id,x,ct);return id;});
    public Task<IReadOnlyList<dynamic>> ListFeedingsAsync(CancellationToken ct)=>List("select * from livestock.feedings where tenant_id=@TenantId order by supplied_on desc limit 500",ct);
    public Task<Guid> AddFeedingAsync(FeedingCommand x,CancellationToken ct)=>Tx(async(c,t)=>{if(x.HeadCount<=0||x.Items.Count==0||x.Items.Any(i=>i.QuantityPerDay<=0))throw new DomainException("Fornecimento inválido.","livestock.feeding_invalid");var id=Guid.CreateVersion7();decimal cost=0;foreach(var i in x.Items){await Consume(c,t,x.WarehouseId,i.ProductId,i.QuantityPerDay,i.Unit,id,"FEEDING",ct);cost+=i.QuantityPerDay*i.UnitCost;}await c.ExecuteAsync(new CommandDefinition("insert into livestock.feedings(id,tenant_id,plan_id,warehouse_id,supplied_on,head_count,total_cost,cost_per_head,notes,created_by) values(@Id,@TenantId,@PlanId,@WarehouseId,@SuppliedOn,@HeadCount,@Cost,@PerHead,@Notes,@UserId)",new{Id=id,tenant.TenantId,x.PlanId,x.WarehouseId,x.SuppliedOn,x.HeadCount,Cost=cost,PerHead=cost/x.HeadCount,x.Notes,tenant.UserId},t,cancellationToken:ct));await Audit(c,t,"create","Feeding",id,x,ct);return id;});
    public Task<IReadOnlyList<dynamic>> ListMilkAsync(CancellationToken ct)=>List("select * from livestock.milk_production where tenant_id=@TenantId order by produced_on desc limit 500",ct);
    public Task<Guid> AddMilkAsync(MilkProductionCommand x,CancellationToken ct)=>Tx(async(c,t)=>{if(x.QuantityLiters<0||x.DiscardedLiters<0||x.DiscardedLiters>x.QuantityLiters)throw new DomainException("Produção ou descarte inválido.","livestock.production_invalid");var id=Guid.CreateVersion7();await c.ExecuteAsync(new CommandDefinition("insert into livestock.milk_production(id,tenant_id,farm_id,animal_id,herd_id,produced_on,quantity_liters,discarded_liters,quality,destination,notes,withdrawal_alert,created_by) values(@Id,@TenantId,@FarmId,@AnimalId,@HerdId,@ProducedOn,@QuantityLiters,@DiscardedLiters,cast(@Quality as jsonb),@Destination,@Notes,exists(select 1 from livestock.animals where tenant_id=@TenantId and id=@AnimalId and withdrawal_until>=@ProducedOn),@UserId)",new{Id=id,tenant.TenantId,x.FarmId,x.AnimalId,x.HerdId,x.ProducedOn,x.QuantityLiters,x.DiscardedLiters,x.Quality,x.Destination,x.Notes,tenant.UserId},t,cancellationToken:ct));await Audit(c,t,"create","MilkProduction",id,x,ct);return id;});
    public Task<IReadOnlyList<dynamic>> WeightGainAsync(CancellationToken ct)=>List("select animal_id,min(occurred_on) initial_date,max(occurred_on) final_date,(array_agg(weight_kg order by occurred_on))[1] initial_weight,(array_agg(weight_kg order by occurred_on desc))[1] final_weight,round(((array_agg(weight_kg order by occurred_on desc))[1]-(array_agg(weight_kg order by occurred_on))[1])/nullif(max(occurred_on)-min(occurred_on),0),4) average_daily_gain from livestock.handling_events where tenant_id=@TenantId and weight_kg is not null group by animal_id having count(*)>1",ct);
    public Task<LivestockDashboardDto> DashboardAsync(CancellationToken ct)=>Tx(async(c,t)=>{using var g=await c.QueryMultipleAsync(new CommandDefinition("select count(*) filter(where status=1),count(*) filter(where status=6),count(*) filter(where status=4 and updated_at>=date_trunc('month',now())),count(*) filter(where withdrawal_until>=current_date) from livestock.animals where tenant_id=@TenantId; select species name,count(*) value from livestock.animals where tenant_id=@TenantId and status=1 group by species; select coalesce(category,'NÃO INFORMADA') name,count(*) value from livestock.animals where tenant_id=@TenantId and status=1 group by category; select count(*) from livestock.herds where tenant_id=@TenantId and active; select coalesce(sum(quantity_liters-discarded_liters),0) from livestock.milk_production where tenant_id=@TenantId and produced_on>=date_trunc('month',current_date); select count(*) filter(where expected_birth_on is not null),count(*) filter(where expected_birth_on between current_date and current_date+interval '60 days') from livestock.reproduction_cycles where tenant_id=@TenantId and status='ACTIVE'; select count(*) from livestock.health_events where tenant_id=@TenantId and next_application between current_date and current_date+interval '30 days'; select count(*) filter(where status='IN_USE'),count(*) filter(where status='RESTING') from livestock.paddocks where tenant_id=@TenantId; select count(*) from livestock.paddocks p where tenant_id=@TenantId and (select count(*) from livestock.animals a where a.tenant_id=p.tenant_id and a.paddock_id=p.id and a.status=1)>p.capacity_au; select coalesce(sum(total_cost),0) from livestock.feedings where tenant_id=@TenantId and supplied_on>=date_trunc('month',current_date); select coalesce(sum(cost_amount),0) from livestock.health_events where tenant_id=@TenantId and occurred_on>=date_trunc('month',current_date)",new{tenant.TenantId},t,cancellationToken:ct));var a=await g.ReadSingleAsync<dynamic>();var species=(await g.ReadAsync<MetricDto>()).ToArray();var categories=(await g.ReadAsync<MetricDto>()).ToArray();var herds=await g.ReadSingleAsync<long>();var milk=await g.ReadSingleAsync<decimal>();var repro=await g.ReadSingleAsync<dynamic>();var vaccines=await g.ReadSingleAsync<long>();var pastures=await g.ReadSingleAsync<dynamic>();var over=await g.ReadSingleAsync<long>();var nutrition=await g.ReadSingleAsync<decimal>();var health=await g.ReadSingleAsync<decimal>();return new((long)a.count,species,categories,herds,(long)a.count1,(long)a.count2,0,milk,(long)repro.count,(long)repro.count1,vaccines,(long)a.count3,(long)pastures.count,(long)pastures.count1,over,nutrition,health);});
    private Task<IReadOnlyList<dynamic>> List(string sql,CancellationToken ct)=>Tx<IReadOnlyList<dynamic>>(async(c,t)=>(await c.QueryAsync(new CommandDefinition(sql,new{tenant.TenantId},t,cancellationToken:ct))).AsList());
    private Task<Guid> Upsert(string table,Guid? id,string columns,string values,string updates,object x,CancellationToken ct)=>Tx(async(c,t)=>{var key=id??Guid.CreateVersion7();var args=new DynamicParameters(x);args.Add("Id",key);args.Add("TenantId",tenant.TenantId);args.Add("UserId",tenant.UserId);var sql=id is null?$"insert into {table}(id,tenant_id,{columns},created_at,created_by) values(@Id,@TenantId,{values},now(),@UserId)":$"update {table} set {updates},updated_at=now(),updated_by=@UserId where tenant_id=@TenantId and id=@Id";var n=await c.ExecuteAsync(new CommandDefinition(sql,args,t,cancellationToken:ct));if(n==0)throw new NotFoundException(table,key);await Audit(c,t,id is null?"create":"update",table,key,x,ct);return key;});
    private async Task Consume(NpgsqlConnection c,NpgsqlTransaction t,Guid? warehouse,Guid? product,decimal quantity,string unit,Guid reference,string type,CancellationToken ct){if(warehouse is null&&product is null)return;if(warehouse is null||product is null)throw new DomainException("Depósito e produto devem ser informados juntos.","inventory.references_required");var row=await c.QuerySingleOrDefaultAsync<dynamic>(new CommandDefinition("select id,available,reserved,average_cost,version,unit from inventory.stock_balances where tenant_id=@TenantId and warehouse_id=@Warehouse and product_id=@Product for update",new{tenant.TenantId,Warehouse=warehouse,Product=product},t,cancellationToken:ct))??throw new ConflictException("Insumo sem saldo.","inventory.insufficient_stock");if((decimal)row.available-(decimal)row.reserved<quantity)throw new ConflictException("Estoque insuficiente.","inventory.insufficient_stock");if(!string.Equals((string)row.unit,unit,StringComparison.OrdinalIgnoreCase))throw new DomainException("Unidade incompatível.","inventory.unit_mismatch");var balance=(decimal)row.available-quantity;await c.ExecuteAsync(new CommandDefinition("update inventory.stock_balances set available=@Balance,version=version+1,updated_at=now() where id=@Id and tenant_id=@TenantId and version=@Version; insert into inventory.stock_movements(id,tenant_id,warehouse_id,product_id,movement_type,quantity,unit,unit_cost,total_cost,reference_type,reference_id,balance_after,average_cost_after,balance_version,occurred_at,created_by) values(@Movement,@TenantId,@Warehouse,@Product,'CONSUMPTION',@Quantity,@Unit,@Cost,@Total,@Type,@Reference,@Balance,@Cost,@NewVersion,now(),@UserId)",new{Balance,Id=(Guid)row.id,tenant.TenantId,Version=(long)row.version,Movement=Guid.CreateVersion7(),Warehouse=warehouse,Product=product,Quantity=quantity,Unit=unit,Cost=(decimal)row.average_cost,Total=quantity*(decimal)row.average_cost,Type=type,Reference=reference,NewVersion=(long)row.version+1,tenant.UserId},t,cancellationToken:ct));}
    private Task Audit(NpgsqlConnection c,NpgsqlTransaction t,string action,string entity,Guid id,object value,CancellationToken ct)=>c.WriteAuditAsync(t,tenant,action,entity,id,null,value,ct);
    private Task<T> Tx<T>(Func<NpgsqlConnection,NpgsqlTransaction,Task<T>> work)=>db.InTenantTransactionAsync(work,CancellationToken.None);
    private Task Tx(Func<NpgsqlConnection,NpgsqlTransaction,Task> work)=>db.InTenantTransactionAsync(work,CancellationToken.None);
    private static int GestationDays(string species)=>species.ToUpperInvariant() switch{"BOVINE" or "BOVINO"=>283,"BUFFALO" or "BUBALINO"=>310,"SHEEP" or "OVINO"=>150,"GOAT" or "CAPRINO"=>150,"SWINE" or "SUINO" or "SUÍNO"=>114,_=>280};
    private static void ValidateWeight(decimal? value){if(value<0)throw new DomainException("Peso não pode ser negativo.","livestock.weight_invalid");}
}
